// node --test tests/*.test.mjs : the original deck in cards/ (generated by tools/make_deck.mjs).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { buildDeck, descModule } from '../tools/make_deck.mjs';
import { CARDS } from '../static/engine.js';

const dir = new URL('../cards/', import.meta.url);
const ids = [...CARDS.map(c => c.id), 'back'];
const read = id => readFileSync(new URL(id + '.svg', dir), 'utf8');

// Minimal XML well-formedness check: balanced tags, quoted attributes, no stray '<' or '&'.
function wellFormed(svg) {
  const stack = [];
  const re = /<(\/?)([a-zA-Z][\w:-]*)((?:\s+[\w:-]+="[^"<]*")*)\s*(\/?)>/g;
  let last = 0, m;
  while ((m = re.exec(svg))) {
    const text = svg.slice(last, m.index);
    if (/[<>]/.test(text) || /&(?!(amp|lt|gt|quot|#\d+);)/.test(text)) return `bad text near ${m.index}`;
    if (m[1]) { if (stack.pop() !== m[2]) return `unbalanced </${m[2]}>`; } else if (!m[4]) stack.push(m[2]);
    last = re.lastIndex;
  }
  return stack.length || svg.slice(last).trim() ? 'unclosed tags' : '';
}

test('78 card files plus the back, and nothing else', () => {
  assert.deepEqual(readdirSync(dir).sort(), ids.map(i => i + '.svg').sort());
});

test('each file is a well-formed, accessible SVG', () => {
  for (const id of ids) {
    const s = read(id);
    assert.ok(s.startsWith('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 520"'), id);
    assert.equal(wellFormed(s), '', id);
    assert.match(s, /role="img" aria-labelledby="t d"><title id="t">[^<]+<\/title><desc id="d">[^<]{40,}<\/desc>/, id);
    assert.ok(!/href="(?!#)/.test(s), `${id}: no external references`);
  }
});

test('titles name the right card', () => {
  for (const c of CARDS) assert.ok(read(c.id).includes(`${c.name}</title>`), c.id);
});

test('the generator is deterministic and the files are up to date', () => {
  const a = buildDeck(), b = buildDeck();
  assert.deepEqual(a, b);
  for (const id of ids) assert.equal(read(id), a[id], `${id} differs: run node tools/make_deck.mjs`);
  assert.equal(readFileSync(new URL('../static/deck_desc.js', import.meta.url), 'utf8'), descModule(a));
});

test('every card is different (art and description)', () => {
  const art = ids.map(id => createHash('sha1').update(read(id).replace(/<title.*?<\/desc>/, '').replace(/<text.*?<\/text>/g, '')).digest('hex'));
  assert.equal(new Set(art).size, ids.length, 'pictures (titles removed) are unique');
  const desc = ids.map(id => read(id).match(/<desc id="d">([^<]+)/)[1]);
  assert.equal(new Set(desc).size, ids.length, 'descriptions are unique');
});

test('size limits: each < 15 kB, all < 1.5 MB', () => {
  let total = 0;
  for (const id of ids) {
    const n = statSync(new URL(id + '.svg', dir)).size;
    assert.ok(n < 15000, `${id} is ${n} bytes`);
    total += n;
  }
  assert.ok(total < 1.5e6, `total ${total}`);
});
